{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    # Build lookup
    node_map = {n['id']: n for n in nodes}
    # Validate all required symbols exist
    all_symbols = {n['symbol'] for n in nodes}
    for sym in required_symbols:
        if sym not in all_symbols:
            raise ValueError(f"Required symbol '{sym}' not present in any node")
    # Initialize state
    present = set(node_map.keys())
    removed_order = []
    # Parent mapping (original, will be updated)
    parent_of = {n['id']: n['parent'] for n in nodes}
    # Depth ordering: deeper first, then id ascending
    depth_order = sorted(node_map.keys(), key=lambda nid: (-node_map[nid]['depth'], nid))
    for nid in depth_order:
        if nid not in present:
            continue
        node = node_map[nid]
        # Conditions: not root, removable, not required symbol
        if nid == 'root' or not node['removable'] or node['symbol'] in required_symbols:
            continue
        # Check for retained children (any child still present)
        has_children = any(pid in present for pid in parent_of if parent_of[pid] == nid)
        if has_children:
            continue
        # Check if removal would preserve all required symbols
        # Count occurrences of each required symbol excluding this node
        ok = True
        for sym in required_symbols:
            found = False
            for other_id in present:
                if other_id == nid:
                    continue
                if node_map[other_id]['symbol'] == sym:
                    found = True
                    break
            if not found:
                ok = False
                break
        if not ok:
            continue
        # Remove node
        removed_order.append(nid)
        present.remove(nid)
        # Promote children to parent of this node
        new_parent = parent_of[nid]
        for child_id in list(parent_of.keys()):
            if parent_of[child_id] == nid:
                parent_of[child_id] = new_parent
    retained = sorted(present)
    return {"removed_node_ids": removed_order, "retained_node_ids": retained}"
}
